steps = [
    step("TCP 层的故障长什么样。在 client 和后端之间放一个我写的 asyncio TCP 代理,后端回 20 KB 的响应体,每种模式 20 个请求,client 的 socket 超时 2 s。直连和透传:20 个都是 200,延迟中位数 1 ms。延迟(每个数据块先等 100 ms):20 个 200,延迟中位数 208 ms(请求和响应各被拖一次)。重置(一连上就发 RST):20 个全是连接被重置,0 ms。黑洞(收下请求但不转发):20 个全是超时,2003 ms。限速(响应 100 KB/s):20 个 200,239 ms。切碎(每个字节单独发):3 个请求全部 200,但每个要 14191 ms,2 s 的超时一次也没触发——socket 超时是两次收到数据之间最多等多久,对端一点一点地发就能把总耗时拖到远超过超时。", t=tl(S(1)), mark=lidx(S(1), '黑洞', '切碎'), done=lidx(S(1), '重置', '延迟:每个数据块', '限速'), b=bars([['延迟注入:中位数 ms', 208, '208'], ['限速 100KB/s:中位数 ms', 239, '239'], ['黑洞:中位数 ms', 2003, '2003(全部超时)'], ['切碎:中位数 ms', 14191, '14191(没有超时)']], 14191, done=[0, 1], mark=[2, 3]), kv=KV([['重置', '连接被重置,0 ms'], ['黑洞', '20 次全部超时 2003 ms'], ['切碎', '一个请求 14 s,2 s 超时没有触发']], ['切碎'])),
    step("应用层的故障注入。服务按概率注入:20% 回 503,另 20% 多等 300 ms,其余 60% 正常 5 ms;client 串行发 400 个请求。不重试、超时 1 s:最终成功 75.5%,延迟中位数 8 ms,p99 311 ms,每个请求发 1.00 次。超时 100 ms、最多共试 3 次:最终成功 94.2%,中位数 8 ms,p99 215 ms,平均每个请求发 1.62 次。每次尝试失败的概率约 0.4(503 加上超过 100 ms 的慢响应),三次都失败约 6.4%,与 94.2% 相符。短超时加重试把成功率拉高、p99 压低,代价是多发 62% 的请求。", t=tl(S(2)), mark=lidx(S(2), '不重试,超时 1 s'), done=lidx(S(2), '超时 100 ms'), b=bars([['不重试:最终成功 %', 75.5, '75.5%'], ['重试:最终成功 %', 94.2, '94.2%'], ['不重试:p99 ms', 311, '311'], ['重试:p99 ms', 215, '215']], 311, mark=[0, 2], done=[1, 3]), kv=KV([['不重试,超时 1 s', '成功 75.5%,p99 311 ms'], ['超时 100 ms,最多 3 次', '成功 94.2%,p99 215 ms,发 1.62 次 / 请求']], ['超时 100 ms,最多 3 次'])),
    step("混沌实验:3 个副本是 3 个独立的 Python 进程,混沌线程每 1.5 秒左右随机 kill -9 一个、0.5 秒后在同一端口拉起,client 100/s 发 12 秒,共 8 次 kill。只连固定的一个副本:请求失败率 9.8%。轮询 3 个副本、不重试:12.2%(期望都是约 13%:8 次 × 0.6 s ÷ 3 ÷ 12 s,区别只是 (a) 取决于被杀的是不是它)。轮询 + 失败换副本重试(最多 3 次):0.0%,平均每个请求发 1.18 次。再加摘除(失败的副本 1 秒内不再选):0.0%,平均每个请求发 1.01 次。四种的成功请求延迟中位数都是 8 ms。重试加换副本把用户可见的失败压到 0,摘除让白发的请求从 18% 降到 1%。", t=tl(S(3)), mark=lidx(S(3), '(a)', '(b)'), done=lidx(S(3), '(c)', '(d)'), b=bars([['(a) 固定副本:失败 %', 9.8, '9.8%'], ['(b) 轮询不重试:失败 %', 12.2, '12.2%'], ['(c) 重试:每个请求发几次', 1.18, '1.18'], ['(d) 重试 + 摘除:每个请求发几次', 1.01, '1.01']], 12.2, mark=[0, 1], done=[2, 3]), kv=KV([['不重试', '失败率 9.8% 到 12.2%'], ['重试换副本', '失败 0.0%,发 1.18 次 / 请求'], ['重试 + 摘除', '失败 0.0%,发 1.01 次 / 请求']], ['重试 + 摘除'])),
]
